% 2. 整合数据
data = [case1; case2; case3; case4; case5; case6; case7];

% 3. 创建热图
fig =figure('Color', [1 1 1]); % 白色背景
% 设置 CellLabelFormat 为 ' ' 可以隐藏格子里拥挤的数字，若需显示可改为 '%.2f'
set(fig, 'Units', 'centimeters', 'Position', [2, 2, 18, 6]); % 建议宽度设为18cm（接近A4纸宽度）
h = heatmap(data, 'CellLabelFormat', '%.2f'); 

% --- 核心修改：锁定颜色映射范围从 0 到 1 ---
h.ColorLimits = [0 1];

% --- 改进 1: 扩展横坐标范围至 1-33 ----20%，-10%，-5%，0%，5%，10%，20%
h.XDisplayLabels = string(1:33);
h.YDisplayLabels = {'-20%', '-10%', '-5%', 'no noise', '+5%', '+10%', '+20%'};

% --- 改进 2: 将标题移动至最右侧 ---
h.Title = 'Fault Recovery Rate'; 

% 其他轴标签设置
h.XLabel = 'Node';
% h.YLabel = 'Algorithm Cases';

% 4. 样式美化
colormap(sky); 
h.GridVisible = 'on'; 
h.FontName = 'Arial';
h.FontSize = 10;

% --- 改进 3: 修改纵横比 ---
% 设置窗口位置和大小：[左, 下, 宽度, 高度]
% 33列属于长条形数据，建议将宽度设为高度的 2.5 到 3 倍
set(gcf, 'Units', 'pixels', 'Position', [100, 100, 1100, 350]);
